<script setup lang="ts">
import '../styles/workspaces.css'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import { useAccount } from '../stores/account'
import {useRoute,useRouter} from 'vue-router'
import type * as echarts from 'echarts/core'
import {workbenchApi,type Overview,type Plant,type Sample,type Point,type Evidence,type Comparison} from '../workbench/api'
import {NOTICE,toggleSelection,groups,chartRows,distributionGroups,distributionRows,contextQuery,sampleQuery} from '../workbench/state'
const route=useRoute(),router=useRouter(),account=useAccount()
const admin=ref(false),overview=ref<Overview|null>(null),plants=ref<Plant[]>([]),samples=ref<Sample[]>([]),points=ref<Point[]>([]),selected=ref<string[]>([]),evidence=ref<Evidence|null>(null),comparison=ref<Comparison|null>(null)
const q=ref(String(route.query.q??'')),kind=ref(String(route.query.kind??'')),part=ref(String(route.query.plantPart??'')),status=ref(String(route.query.status??'')),source=ref(String(route.query.sourceId??'')),unlinked=ref(route.query.unlinked==='true'),error=ref(''),busy=ref(false),chart=ref<HTMLElement|null>(null),chartObj=ref<echarts.ECharts|null>(null)
const displayMode=ref<'parallel'|'composition'|'table'>('parallel'),sampleIds=ref(String(route.query.sampleIds??'').split(',').filter(Boolean).slice(0,4)),sampleCursor=ref<string|null>(null),samplesMore=ref(false),pointCursor=ref<string|null>(null),pointsMore=ref(false),pointsCapped=ref(false),chartGroup=ref('')
let controller:AbortController|null=null,evidenceController:AbortController|null=null,compareController:AbortController|null=null,epoch=0,evidenceEpoch=0,compareEpoch=0,resizeObserver:ResizeObserver|null=null
const groupsList=computed(()=>displayMode.value==='composition'?distributionGroups(points.value):groups(points.value)),activePoints=computed(()=>groupsList.value.find(([key])=>key===chartGroup.value)?.[1]??groupsList.value[0]?.[1]??[]),rowsForChart=computed(()=>displayMode.value==='composition'?distributionRows(activePoints.value):chartRows(activePoints.value)),sourceVersionCount=computed(()=>overview.value?.sources.filter(x=>!x.key.startsWith('file:')).length??0)
function confidenceLabel(value:string|null){return ({HUMAN_VERIFIED:'人工核验',SOURCE_REPORTED:'资料中记载',MACHINE_EXTRACTED:'自动提取'} as Record<string,string>)[value??'']??'可信度未知'}
function cancelEvidence(){evidenceController?.abort();evidenceController=null;evidenceEpoch++;evidence.value=null}
function cancelCompare(){compareController?.abort();compareController=null;compareEpoch++;comparison.value=null}
function clearPrivate(){chartObj.value?.clear();busy.value=false;controller?.abort();cancelEvidence();compareController?.abort();compareEpoch++;epoch++;overview.value=null;plants.value=[];samples.value=[];points.value=[];selected.value=[];comparison.value=null;sampleIds.value=[];sampleCursor.value=null;pointCursor.value=null;samplesMore.value=false;pointsMore.value=false;pointsCapped.value=false;error.value=''}
function escapeHtml(value:string){return value.replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]??c))}
let disposed=false
async function renderChart(){if(!chart.value)return;const group=activePoints.value,rows=rowsForChart.value,plotted=rows.filter(x=>x.value!==null);if(!plotted.length){chartObj.value?.clear();return}const host=chart.value,renderEpoch=epoch,renderMode=displayMode.value,renderGroup=chartGroup.value;const {echarts:runtime}=await import('../workbench/charts');if(disposed||host!==chart.value||renderEpoch!==epoch||renderMode!==displayMode.value||renderGroup!==chartGroup.value||!chart.value||displayMode.value==='table'||!rowsForChart.value.some(x=>x.value!==null))return;if(!chartObj.value)chartObj.value=runtime.init(chart.value);const unit=group.find(x=>x.unit)?.unit||'单位未提供';chartObj.value.setOption({title:{text:displayMode.value==='composition'?'单样本脂肪酸组分分布':'样本测量记录',subtext:`${plotted.length} 条有数值的记录 · 单位：${unit}`,left:'center',textStyle:{color:'#294132',fontSize:14},subtextStyle:{color:'#637164'}},aria:{enabled:true,description:`描述性记录图：${plotted.length}条数值，单位${unit}；${displayMode.value==='composition'?'同一科学样本内分别显示脂肪酸组分':'按样本与分析物分别显示'}；不同基础分组，不构成科学确认。`},tooltip:{trigger:'axis',formatter:(items:any[])=>items.map(item=>{const row=rows.find(x=>x.id===item.data.id);return `${escapeHtml(row?.fullLabel??row?.analyte??'记录')}<br/>记录ID：${escapeHtml(row?.id??'')}<br/>数值：${item.data.value} ${escapeHtml(unit)}`}).join('<br/><br/>')},grid:{left:55,right:20,top:65,bottom:95},xAxis:{type:'category',data:plotted.map(x=>x.label),axisLabel:{rotate:35,interval:0}},yAxis:{type:'value',name:unit},series:[{type:'bar',data:plotted.map(x=>({value:x.value,id:x.id})),itemStyle:{color:'#52745d'}}]});chartObj.value.off('click');chartObj.value.on('click',(p:any)=>{if(p.data?.id)void openEvidence(String(p.data.id))})}
function deferChart(){requestAnimationFrame(renderChart)}
async function enterAdmin(){try{const r=await fetch('/api/v1/admin/session',{credentials:'include',headers:{Accept:'application/json'}});const session=await r.json();if(!r.ok||!session.roles?.some((x:string)=>['admin','role_admin'].includes(x.toLowerCase())))throw new Error('请先在审核台登录管理员账户，再查看候选范围。');admin.value=true;await router.replace({query:{...route.query,scope:'admin'}})}catch(e){error.value=(e as Error).message}}
function handleFailure(e:unknown){if([401,403].includes((e as {status?:number}).status??0)&&admin.value)leaveAdmin();error.value=(e as Error).message}
function leaveAdmin(){admin.value=false;void router.replace({query:{...route.query,scope:undefined}})}
function selectPlant(event:Event){const value=(event.target as HTMLSelectElement).value;void router.replace({query:{...route.query,plantId:value||undefined}})}
function query(){return sampleQuery({q:q.value,plantId:route.query.plantId?String(route.query.plantId):undefined,sourceId:source.value,kind:kind.value,plantPart:part.value,status:status.value,unlinked:unlinked.value,limit:'20'})}
async function load(){controller?.abort();cancelEvidence();compareController?.abort();compareEpoch++;controller=new AbortController();const signal=controller.signal,n=++epoch;error.value='';busy.value=true;{chartObj.value?.clear();overview.value=null;plants.value=[];samples.value=[];points.value=[];selected.value=[];comparison.value=null}try{const ov=await workbenchApi.overview(admin.value,signal),pl=await workbenchApi.plants(q.value,admin.value,signal),page=await workbenchApi.samples(query(),admin.value,signal);if(n!==epoch)return;overview.value=ov;plants.value=pl;samples.value=page.items;sampleCursor.value=page.nextCursor;samplesMore.value=page.hasMore;pointCursor.value=null;pointsMore.value=false;pointsCapped.value=false;selected.value=[];comparison.value=null;if(sampleIds.value.length)await loadPoints(false);else deferChart()}catch(e){if(!signal.aborted&&n===epoch){error.value=(e as Error).message;if([401,403].includes((e as {status?:number}).status??0)&&admin.value){admin.value=false;router.replace({query:{...route.query,scope:undefined}})}}}finally{if(n===epoch)busy.value=false}}
async function toggleSample(id:string){const next=sampleIds.value.includes(id)?sampleIds.value.filter(x=>x!==id):sampleIds.value.length<4?[...sampleIds.value,id]:sampleIds.value;if(next===sampleIds.value)return;sampleIds.value=next;points.value=[];pointCursor.value=null;pointsMore.value=false;pointsCapped.value=false;selected.value=[];cancelEvidence();cancelCompare();if(!next.length){deferChart();return}await loadPoints(false)}
async function loadPoints(more=true){controller?.abort();cancelEvidence();controller=new AbortController();const signal=controller.signal,n=++epoch,offset=more?pointCursor.value:null;busy.value=true;try{const pp=await workbenchApi.points(sampleIds.value,{kind:kind.value,limit:'60',...(offset?{cursor:offset}:{})},admin.value,signal);if(n!==epoch)return;const merged=more?[...points.value,...pp.items.filter(x=>!points.value.some(old=>old.id===x.id))]:pp.items;points.value=merged.slice(0,120);pointCursor.value=pp.nextCursor;pointsMore.value=pp.hasMore&&merged.length<120;pointsCapped.value=merged.length>=120&&pp.hasMore;deferChart()}catch(e){if(!signal.aborted&&n===epoch)handleFailure(e)}finally{if(n===epoch)busy.value=false}}
async function loadMoreSamples(){if(!sampleCursor.value||busy.value)return;controller?.abort();controller=new AbortController();const signal=controller.signal,n=++epoch;busy.value=true;try{const p=await workbenchApi.samples({...query(),cursor:sampleCursor.value},admin.value,signal);if(n!==epoch)return;const seen=new Set(samples.value.map(s=>s.id));samples.value=[...samples.value,...p.items.filter(s=>!seen.has(s.id))];sampleCursor.value=p.nextCursor;samplesMore.value=p.hasMore}catch(e){if(!signal.aborted&&n===epoch)handleFailure(e)}finally{if(n===epoch)busy.value=false}}
function choosePoint(id:string){selected.value=toggleSelection(selected.value,id);cancelCompare();void openEvidence(id)}
async function openEvidence(id:string){cancelEvidence();const n=++evidenceEpoch,scope=admin.value,request=new AbortController();evidenceController=request;try{const result=await workbenchApi.evidence(id,scope,request.signal);if(n===evidenceEpoch&&scope===admin.value)evidence.value=result}catch(e){if(!request.signal.aborted&&n===evidenceEpoch){handleFailure(e);evidence.value=null}}}
async function compare(){if(selected.value.length<2)return;compareController?.abort();const request=new AbortController();compareController=request;const n=++compareEpoch,scope=admin.value;comparison.value=null;try{const result=await workbenchApi.compare(selected.value,scope,request.signal);if(n===compareEpoch&&scope===admin.value)comparison.value=result}catch(e){if(!request.signal.aborted&&n===compareEpoch)handleFailure(e)}}
function assistant(){const c={plantId:Number(route.query.plantId)||undefined,sampleIds:sampleIds.value,sourceId:source.value||undefined,kind:kind.value||undefined,plantPart:part.value||undefined};router.push({path:'/assistant',query:{context:contextQuery(c)}})}
function persistFilters(){const query={...route.query,q:q.value||undefined,plantId:route.query.plantId,sourceId:source.value||undefined,kind:kind.value||undefined,plantPart:part.value||undefined,status:status.value||undefined,unlinked:unlinked.value?'true':undefined,sampleIds:sampleIds.value.length?sampleIds.value.join(','):undefined};void router.replace({query})}
watch([q,kind,part,status,source,unlinked,admin,()=>route.query.plantId],()=>{persistFilters();void load()})
watch(sampleIds,()=>persistFilters(),{deep:true})
watch(chart,element=>{resizeObserver?.disconnect();resizeObserver=null;chartObj.value?.dispose();chartObj.value=null;if(element){resizeObserver=new ResizeObserver(()=>chartObj.value?.resize());resizeObserver.observe(element);deferChart()}})
watch([chartGroup,displayMode],()=>{cancelEvidence();deferChart()})
watch(admin,(value,old)=>{if(value!==old)clearPrivate()},{flush:'sync'})
onMounted(async()=>{const initialSamples=[...sampleIds.value];if(route.query.scope==='admin'){try{const r=await fetch('/api/v1/admin/session',{credentials:'include',headers:{Accept:'application/json'}});const s=await r.json();admin.value=r.ok&&s.roles?.some((x:string)=>['admin','role_admin'].includes(x.toLowerCase()))}catch{admin.value=false}if(!admin.value)await router.replace({query:{...route.query,scope:undefined}})}sampleIds.value=initialSamples;await load()})
onUnmounted(()=>{disposed=true;controller?.abort();cancelEvidence();compareController?.abort();epoch++;compareEpoch++;resizeObserver?.disconnect();chartObj.value?.dispose()})
</script>
<template>
<main class="wb-page"><header class="wb-head"><div><p class="section-kicker">VIRIDEXA SCIENTIFIC WORKBENCH</p><h1>植序科研实验台</h1><p>按植物、样本、来源与测量记录探索数据，并逐条回到证据。</p></div><button class="plain-button" @click="assistant">将筛选条件交给研究助手</button></header>
<p class="wb-warning">{{admin?NOTICE:(overview?.notice??'正在读取公开范围说明。')}} 图表仅作描述性展示；不同计量基础不作换算，不代表科学确认。</p><div class="wb-mode"><span>{{admin?'管理员候选范围':'公开范围'}}</span><RouterLink v-if="!admin&&account.isAdmin" to="/review">前往审核工作台 →</RouterLink><button v-if="!admin&&account.isAdmin" class="plain-button" @click="enterAdmin">查看管理员候选范围</button><button v-else-if="admin" @click="leaveAdmin">切换公开范围</button><RouterLink to="/knowledge-graph">浏览知识图谱 →</RouterLink></div><p v-if="error" role="alert" class="assistant-error">{{error}} <button class="plain-button" @click="load">重新读取数据</button></p><p v-if="busy" class="wb-state" role="status">正在读取当前范围的数据…</p>
<p v-if="overview&&overview.publishedFactCount===0" class="wb-state">当前没有人工核验并正式发布的科学事实。已获公开授权的来源记载或自动提取记录仍可在下方样本中查看；它们不等同于人工核验结论。请前往<RouterLink to="/review">审核工作台</RouterLink>查看候选，或浏览<RouterLink to="/knowledge-graph">知识图谱</RouterLink>中的来源与目录记录。</p><section v-if="overview" class="wb-stats"><div><b>{{overview.publishedFactCount}}</b><span>公开事实</span></div><div><b>{{overview.visibleSamples}}</b><span>可见样本</span></div><div><b>{{overview.unlinkedSamples}}</b><span>未关联样本</span></div><div><b>{{overview.sources.reduce((a,s)=>a+s.count,0)}}</b><span>样本关联记录和（可重复）</span><small>来源版本 {{sourceVersionCount}} / 当前范围来源条目 {{overview.sources.length}}；关联样本数合计 {{overview.sources.reduce((a,s)=>a+s.count,0)}}（同一样本可关联多个来源，合计不等于唯一样本数）</small></div></section>
<details v-if="overview" class="wb-overview"><summary>记录覆盖与来源目录 · {{overview.sources.length}} 个来源入口</summary><div class="wb-bars"><div v-for="(item,index) in [...overview.states,...overview.kinds,...overview.sources]" :key="`${index}:${item.key}`" class="wb-bar"><span>{{item.label||item.key}}</span><meter min="0" :max="Math.max(1,...[...overview.states,...overview.kinds,...overview.sources].map(x=>x.count))" :value="item.count"></meter><b>{{item.count}}</b></div></div></details>
<section class="wb-filters"><label>搜索<input v-model="q" placeholder="搜索植物、样本或测量"/></label><label>来源<select v-model="source"><option value="">全部来源</option><option v-for="s in overview?.sources??[]" :key="s.key" :value="s.key">{{s.label}}（{{s.count}}）</option></select></label><label>记录类型<select v-model="kind"><option value="">全部类型</option><option value="OIL_CONTENT">含油率</option><option value="OIL_FA_COMPOSITION">种子油脂肪酸组成</option><option value="FAME_COMPOSITION">FAME脂肪酸组成</option><option value="FOOD_NUTRIENT">食品脂肪酸营养记录</option></select></label><label>植物部位<input v-model="part" placeholder="按服务端字段筛选"/></label><label v-if="admin">审核状态<select v-model="status"><option value="">全部状态</option><option value="PENDING">待审核</option><option value="HELD">隔离待补充</option><option value="APPROVED">已批准</option><option value="REJECTED">已拒绝</option><option value="NEEDS_EVIDENCE">退回补证</option><option value="REVOKED">已撤回</option><option value="LEGACY_REVIEW_REQUIRED">历史记录待具名复核</option></select></label><label v-if="admin" class="wb-check"><input v-model="unlinked" type="checkbox"/> 仅未关联样本</label></section>
<div class="wb-columns"><aside class="wb-research-rail" aria-label="研究对象与筛选结果"><details open class="wb-object-panel"><summary>研究对象 / 植物</summary><label class="wb-filter-label">植物过滤<select :value="String(route.query.plantId??'')" @change="selectPlant"><option value="">全部植物</option><option v-for="p in plants" :key="p.id" :value="String(p.id)">{{p.nameZh||p.scientificName}}</option></select></label><ul class="wb-list"><li v-for="p in plants" :key="p.id"><RouterLink :to="`/plants/${p.id}${admin?'?scope=admin':''}`"><b>{{p.nameZh||p.scientificName}}</b><small>{{p.scientificName}} · {{p.identityState}}</small></RouterLink></li></ul><p v-if="!plants.length&&!busy&&!error">当前筛选没有植物记录。可打开<template v-if="account.isAdmin"><RouterLink to="/review">审核工作台</RouterLink>或</template><RouterLink to="/knowledge-graph">知识图谱</RouterLink>查看对应范围。</p>
<h3>样本 <small>最多选择 4 个</small></h3></details><details open class="wb-object-panel"><summary>样本 · 最多选择 4 个</summary><ul class="wb-list"><li v-for="s in samples" :key="s.id"><label><input type="checkbox" :checked="sampleIds.includes(s.id)" :disabled="!sampleIds.includes(s.id)&&sampleIds.length>=4" @change="toggleSample(s.id)"/><b>{{s.label||s.sampleKey}}</b></label><small>{{s.id}} · {{s.measurementCount}} 条测量 · {{s.linkageState}} · {{s.plantPart||'部位未提供'}}</small><small v-if="s.sources.length">来源：{{s.sources.map(x=>x.displayLabel).join('、')}} · 范围：{{overview?.scope}}</small></li></ul><p v-if="!samples.length&&!busy&&!error" class="wb-state">当前范围没有可见样本。公开样本可能为 0；<template v-if="account.isAdmin">需候选审核时请<RouterLink to="/review">前往审核工作台</RouterLink>；</template>可打开<RouterLink to="/knowledge-graph">知识图谱</RouterLink>查看可用节点。</p><button v-if="samplesMore" class="plain-button" :disabled="busy" @click="loadMoreSamples">加载更多样本</button></details></aside>
<section class="wb-data-panel"><h2>测量记录 <small>{{points.length}} 条</small></h2><nav class="wb-view-modes" aria-label="测量展示模式"><button :aria-pressed="displayMode==='parallel'" @click="displayMode='parallel';chartGroup=''">样本指标并列</button><button :aria-pressed="displayMode==='composition'" @click="displayMode='composition';chartGroup=''">单样本组分分布</button><button :aria-pressed="displayMode==='table'" @click="displayMode='table';chartGroup=''">数据列表</button></nav><p v-if="displayMode==='composition'" class="wb-state">仅显示种子油脂肪酸组分（FAME/OIL_FA）；每组固定一个样本、类型、基础和单位，数值按原记录并列，不归一化到 100，也不纳入食品营养记录。</p><div v-if="groupsList.length>1" class="wb-facets"><span>基础、单位或分析物不同，分组显示：</span><button v-for="([key]) in groupsList" :key="key" :aria-pressed="chartGroup===key" @click="chartGroup=key">{{key}}</button></div><p v-if="sampleIds.length&&!points.length&&!busy" class="wb-state">所选样本暂无此类型的可用测量记录。脂肪酸与含油率按服务端记录分别查看。</p><p v-if="!sampleIds.length&&!busy&&!error" class="wb-state">先从左侧选择样本，再查看其真实测量记录。</p><p v-if="points.length&&activePoints.every(x=>x.value==null)" class="wb-state">当前组的数值均未提供，表格仍保留来源记录。</p><div v-if="displayMode!=='table'&&activePoints.some(x=>x.value!==null)" ref="chart" class="wb-chart" role="img" :aria-label="`描述性记录图，单位 ${activePoints.find(x=>x.unit)?.unit||'未提供'}；不同样本独立显示，不代表科学确认`"></div>
<table v-if="points.length"><caption>{{displayMode==='composition'?'当前单一样本脂肪酸组分的数据表':'当前测量组的无障碍文本数据表'}}</caption><thead><tr><th>样本 / 分析物</th><th>数值</th><th>单位</th><th>基础</th></tr></thead><tbody><tr v-for="r in rowsForChart" :key="r.id"><td>{{displayMode==='composition'?`${r.sampleId} · ${r.analyte}`:r.fullLabel}}</td><td>{{r.value??'未提供数值'}}</td><td>{{activePoints.find(p=>p.id===r.id)?.unit||'—'}}</td><td>{{activePoints.find(p=>p.id===r.id)?.basis||'—'}}</td></tr><tr v-for="p in activePoints.filter(x=>x.value==null&&displayMode!=='composition')" :key="p.id"><td>{{p.sampleId}} · {{p.analyte||p.kind}}</td><td>{{p.rawValue||'未提供数值'}}</td><td>{{p.unit||'—'}}</td><td>{{p.basis||'—'}}</td></tr></tbody></table>
<h3>选择记录查看证据</h3><table v-if="points.length"><thead><tr><th>选择</th><th>样本 / 分析物</th><th>数值</th><th>状态</th></tr></thead><tbody><tr v-for="p in points" :key="p.id"><td><input type="checkbox" :aria-label="`选择 ${p.sampleId} ${p.analyte||p.kind} 进行比较`" :checked="selected.includes(p.id)" @change="choosePoint(p.id)"/><button class="wb-evidence-button" @click="openEvidence(p.id)">查看证据</button></td><td>{{p.sampleId}} · {{p.analyte||p.kind}}<small>{{p.id}}</small></td><td>{{p.value??'—'}} {{p.unit||''}}<small>{{p.rawValue??''}}</small></td><td>{{p.reviewState}} · {{p.publicationState}}</td></tr></tbody></table><button v-if="pointsMore" class="plain-button" @click="loadPoints(true)">加载更多测量</button><p v-if="pointsCapped" class="wb-cap">已达到 120 条测量的工作台上限；可继续缩小筛选范围。</p><button class="plain-button" :disabled="selected.length<2" @click="compare">服务端比较所选 {{selected.length}} 条</button><section v-if="comparison" class="wb-comparison" aria-live="polite"><h3>{{comparison.conclusion}}</h3><p>{{comparison.notice}}</p><ul><li v-for="c in comparison.checks" :key="c.dimension"><b>{{c.dimension}} · {{c.status}}</b><br/>{{c.reason}}</li></ul></section></section>
<aside class="wb-inspector" aria-label="证据与可比性检查器"><h2>证据检查器</h2><template v-if="evidence"><b>{{evidence.point.id}}</b><dl class="wb-evidence-fields"><dt>研究样本</dt><dd>{{evidence.point.sampleId}}</dd><dt>原始值</dt><dd>{{evidence.point.rawValue??'未提供'}}</dd><dt>标准化值</dt><dd>{{evidence.point.value??'未提供'}} {{evidence.point.unit||''}}</dd><dt>计量基础</dt><dd>{{evidence.point.basis||'未提供，不能推定'}}</dd><dt>实验方法</dt><dd>{{evidence.point.method||'未记录实验方法'}}</dd><dt>身份 / 部位</dt><dd>{{evidence.point.identityState}} / {{evidence.point.plantPart||'未提供'}}</dd><dt>公开级别 / 可信度</dt><dd>{{evidence.point.publicationState}} / {{confidenceLabel(evidence.point.knowledgeConfidence)}}</dd><dt>来源位置</dt><dd>{{JSON.stringify(evidence.point.locator)}}</dd></dl><p>{{evidence.point.rawValue??'—'}} {{evidence.point.unit||''}} · {{evidence.availability}}</p><ul><li v-for="s in evidence.sources" :key="s.sourceId">来源 {{s.sourceId}} · {{s.displayLabel}} · {{s.licenseState??'许可未知'}}</li></ul><details class="wb-lineage-detail"><summary>展开完整来源链结构</summary><pre>{{JSON.stringify(evidence.lineage,null,2)}}</pre></details><RouterLink v-if="evidence.point.graphNodeId" :to="{path:'/knowledge-graph',query:{nodeId:evidence.point.graphNodeId,scope:admin?'admin':undefined}}">在知识图谱中查看 ↗</RouterLink><a v-if="evidence.reviewUrl&&admin" :href="evidence.reviewUrl">审核记录 ↗</a></template><p v-else>选择一条测量记录查看其来源、定位和数据沿袭。</p><p>比较结果仅说明字段兼容性，不形成科学结论。</p></aside></div></main>
</template>
